-- Sección «Devoción a Nuestra Santísima Madre de la Merced» de la landing (HU-32).
-- Agrega solo la clave devocion: conserva el resto del contenido editado.
UPDATE contenido_landing
SET contenido = JSON_SET(contenido, '$.devocion', JSON_EXTRACT('{"d":{"titulo":"Devoción a Nuestra Santísima Madre de la Merced","descripcion":"Cómo honramos a la Madre de Dios y a los santos de la Orden.","oracion":{"titulo":"¡Quédate con nosotros, Señor!","texto":"Padre nuestro, te damos gracias por la casa en que vivimos. Te invocamos con ánimo agradecido para que derrames tu abundante bendición sobre nuestra familia. Necesitamos ese regalo generoso y te lo pedimos con fe sincera y la confianza de hijos. Te damos gracias de todo corazón por tu bondad paternal.\\n\\nAsístenos en todo momento, para que sintamos tu presencia protectora, no como huésped, sino como Padre amoroso que cuida de sus hijos. Ahuyenta todo mal de nuestros corazones y de esta casa.\\n\\nQue la sagrada Familia de Nazaret sea nuestro modelo de fe sencilla y de disponibilidad total a cumplir tu Voluntad.\\n\\nQue practiquemos las virtudes que nos infundiste en el Bautismo y seamos ejemplo de vida cristiana para cuantos se relacionen con nosotros.\\n\\nAyúdanos a sobrellevar con paciencia las pruebas en la enfermedad, en la vejez y en todas las contrariedades que se nos presenten.\\n\\nImploramos tu ayuda para realizar todo en el nombre del Padre, del Hijo y del Espíritu Santo.\\n\\nAmén."},"tarjetas":[{"titulo":"Conocer e imitar a María","descripcion":"Para conocerla mejor e imitarla, los mercedarios estudiamos con particular interés la figura de María; con sencillez y competencia debemos exponer su misión y privilegios, y con nuestra vida y ejemplo hemos de ser promotores de auténtico culto mariano."},{"titulo":"Cómo honramos a la Madre de Dios","descripcion":"Honramos a la Madre de Dios en especial con los siguientes actos:\\n1° Rezo diario de una parte del rosario;\\n2° Los sábados, según las leyes litúrgicas, misa de nuestra santísima Madre, y liturgia de las horas de Santa María; y a la hora oportuna canto de la Salve;\\n3° En el último sábado de mes, plegarias especiales por los cristianos oprimidos;\\n4° Celebración solemne de su festividad, el 24 de septiembre;\\n5° Dedicación de las provincias, iglesias y oratorios;\\n6° Presencia de su imagen en los coros y habitaciones."},{"titulo":"Honramos a nuestro Padre","descripcion":"Honramos a nuestro Padre celebrando en cada comunidad solemnemente su fiesta, exponiendo sus virtudes y ejemplos a los fieles, instruyendo a los terciarios, cofrades y otros asociados a nuestra Orden en el conocimiento de su vida y obra; y con el canto de alguna alabanza en su honor después del canto de la Salve sabatina."},{"titulo":"Los santos de la Orden","descripcion":"Honramos también a los santos de la Orden imitando sus virtudes, dedicándoles, donde sea conveniente, provincias, casas e iglesias y extendiendo su devoción entre los fieles."}]}}', '$.d'))
WHERE id = 1;
